    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Sistem genelindeki ayarları yapılandırın: Temel URL, güvenlik, varsayılan dil, saat dilimi, risk puanlama varsayılanları ve daha fazlası.',
    'SettingsPreferencesDesc'             => 'SimpleRisk genelindeki varsayılan değerler ve davranış tercihleri: dil, saat dilimi, denetim durumları, risk eşleme gereksinimleri, kullanıcı arayüzü davranış anahtarları ve benzerleri.',
