    'HealthCheckDesc'                     => 'Sistem durumunu teşhis edin: PHP sürümü, uzantılar, dosya izinleri, veritabanı bağlantısı, cron zamanlaması ve Ekstra etkinleştirmeleri.',
    'AnnouncementsDesc'                   => 'Tüm kullanıcılara görünür banner duyuruları oluşturun ve yönetin.',
    'RegisterAndUpgradeDesc'              => 'SimpleRisk kurulumunuzu kaydedin, abonelik anahtarınızı girin veya yenileyin ve tek tıklamayla Temel/Ekstra yükseltmeleri başlatın.',
    'QueueMonitorDesc'                    => 'Arka plan iş kuyruğunu inceleyin: beklemede olan, devam eden ve başarısız olan işler.',
    'ExtrasDesc'                          => 'SimpleRisk Ekstralarını (ücretli eklenti modülleri) etkinleştirin, devre dışı bırakın ve yapılandırın.',
    'ArtificialIntelligenceExtraDesc'     => 'Yapay Zeka Ekstrası, gelişmiş risk analizi (FAIR değerlendirmeleri dahil) ve özelleştirilmiş belgeler sağlar.',
    'CustomizationExtraDesc'              => 'Özelleştirme Ekstrası, farklı alan türlerini ekleme ve kaldırma ve dinamik olarak özel sayfa şablonları oluşturma olanağı sağlar.',
    'NotificationExtraDesc'               => 'E-posta Bildirimi Ekstrası, SimpleRisk\'in riskler gönderildiğinde, değiştirildiğinde veya üzerinde başka bir işlem yapıldığında e-posta bildirimleri göndermesini sağlar. Bu ekstra, risklerin yönetim incelemesine hazır olduğu durumlarda rutin hatırlatmalar göndermek üzere zamanlanmış bir betik olarak da eklenebilir. SimpleRisk Core ürününde, bu Ekstra olmadan, araç dışına hiçbir bildirim iletilmez.',
    'VulnerabilityManagementExtraDesc'    => 'Zafiyet Yönetimi Ekstrası, müşterilere SimpleRisk örneklerini Qualys, Tenable.io veya Rapid7 Nexpose/InsightVM ile entegre etme ve hem varlık hem de zafiyet verilerini SimpleRisk\'e aktarma olanağı sağlar. Buradan hangi siteleri kapsamak istediğinizi seçebilir, hangi zafiyet puanlarının içe aktarılacağını belirleyebilir ve hangi zafiyetlerin takip edilmek üzere risklere dönüştürüleceğini önceliklendirebilirsiniz.',
    'IncidentManagementExtraDesc'         => 'Olay Yönetimi Ekstrası, NIST 800-61 Bilgisayar Güvenliği Olay Yönetimi Kılavuzu\'nu temel alır ve SimpleRisk sistemi içinde olay yönetimi yetenekleri sağlar.',

    // Configure Hub - tile descriptions (customization category)
