    'RiskConfigurationDesc'               => 'Risk puanlama kurallarını yapılandırın: düzeyler, risk iştahı, SLA eşikleri ve klasik / katkıda bulunan risk formülleri.',
    'RiskAndThreatCatalogDesc'            => 'Açılır menülerde kullanılan risk ve tehdit değerleri kataloğunu güncel tutun.',
    'AddAndRemoveValuesDesc'              => 'Risk alanları için açılır menü değerlerini yönetin: konum, kaynak, kategori, ekip, teknoloji ve daha fazlası.',
