    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Kullanıcı ekleyin, düzenleyin, devre dışı bırakın ve sıfırlayın; parola ilkesini yönetin.',
    'RoleManagementDesc'                  => 'Rolleri ve her rolün verdiği izinleri tanımlayın.',
    'TeamManagementDesc'                  => 'Kayıt görünürlüğü filtrelemesi için kullanılan ekipleri oluşturun ve yönetin.',
    'SeparationExtraDesc'                 => 'Ekip Tabanlı Ayrım Ekstrası, risk görüntülemeyi yalnızca riskin atandığı ekibin üyesi olan kullanıcılarla sınırlar. SimpleRisk Core ürününde, bu Ekstra olmadan, her kullanıcı her riski görebilir.',
    'CustomAuthenticationExtraDesc'       => 'Özel Kimlik Doğrulama Ekstrası, Active Directory ve SAML kimlik doğrulaması için destek sağlar. SimpleRisk Core ürününde, bu Ekstra olmadan tek seçenek SimpleRisk kimlik deposunda yeni kullanıcılar oluşturmaktır.',
    'EncryptionExtraDesc'                 => 'Şifreli Veritabanı Ekstrası, rastgele bir AES-256 bit şifreleme anahtarı oluşturur ve bunu hassas metinleri SimpleRisk veritabanına eklenmeden önce şifrelemek için kullanır. Bu, kimsenin SimpleRisk uygulamasını doğrudan kullanmadan verileri görüntülemesini veya değiştirmesini engeller.',
    'OrganizationManagementDesc'          => "Organizasyonel Hiyerarşi Ekstrası, herhangi bir sayıda ekip içerebilen birden fazla İş Birimi tanımlama olanağı sağlar. Kullanıcılar daha sonra çeşitli İş Birimleri altındaki bir veya daha fazla ekibe atanabilir. Bu durum, kullanıcının ilişkili olmadığı ekipleri, kullanıcıları ve varlıkları görme ve kullanma yeteneğini etkiler.",

