    'DeleteRisksDesc'                     => 'Riskleri toplu olarak silin. Dikkatli kullanın; silme işlemleri kalıcıdır.',
    'AuditTrailDesc'                      => 'Kullanıcı eylemlerine ait sistem denetim günlüğünü arayın ve dışa aktarın.',
    'ImportExportExtraDesc'               => 'İçe-Dışa Aktarma Ekstrası, bir CSV dosyasındaki alanları SimpleRisk veritabanındaki alanlarla eşleyerek verileri SimpleRisk\'e aktarma olanağı sağlar. Üçüncü taraf bir elektronik tablodan denetim sonuçlarını, başka bir araçtan zafiyet tarama sonuçlarını, CMDB\'nizden varlıkları ve daha fazlasını içe aktarmak için kullanılabilir. Ekstra ayrıca SimpleRisk\'ten Riskleri, Mitigasyonları, İncelemeleri veya üçünün Birleşik raporunu içeren CSV dosyalarını dışa aktarma olanağı da sağlar.',
    'JiraExtraDesc'                       => 'Jira Entegrasyonu Ekstrası, kullanıcılara bir Jira örneğiyle çift yönlü entegrasyon olanağı sağlar. Risklerin Jira Sorunlarına bağlanmasını ve bunların verilerinin, durumunun ve yorumlarının senkronize edilmesini sağlar.',
    'APIExtraDesc'                        => 'API Ekstrası, müşterilerin gelişmiş otomasyon elde etmek ve mevcut altyapıdan yararlanmak için diğer uygulamalarla betikli etkileşimler oluşturmak üzere RESTful API kullanmasına izin verir.',
    'AdvancedSearchExtraDesc'             => 'Gelişmiş Arama Ekstrası, üst çubuktaki arama kutusunu riskler, çerçeveler, kontroller, belgeler, istisnalar, testler, denetimler, varlıklar ve varlık grupları genelinde tek bir aramaya dönüştürür ve sonuçları incelemek için tam bir Arama sayfası sunar. Yalnızca kullanıcının görmesine izin verilen kayıtları gösterir.',
    'AssessmentsExtraDesc'                => 'Risk Değerlendirme Ekstrası, kullanıcılara iletişim kişilerini tanımlama, sorular oluşturma (mantık dahil), bir anket şablonuyla birden fazla soruyu bir araya getirme, anketler oluşturup iletişim kişilerine gönderme, anket sonuçlarını görüntüleme, bu sonuçlara göre risk ekleme ve sonuçları zaman içinde karşılaştırma, harici olarak özelleştirilmiş değerlendirmeleri içe ve dışa aktarma ve risk değerlendirme denetim izini inceleme olanağı sağlar.',
    'ActiveAssessmentsDesc'               => 'Şu anda devam eden değerlendirmeleri görüntüleyin ve yönetin.',
    'WorkflowsExtraDesc'                  => 'Workflows Extra, SimpleRisk içindeki olaylara yanıt olarak risk yönetimi eylemlerini otomatikleştiren görsel, olay odaklı bir iş akışı motoru sağlar. Bir riskin gönderilmesi, güncellenmesi veya incelenmesi gibi değişikliklerde tetiklenen iş akışları tasarlayarak onayları yönlendirebilir, iş atayabilir ve manuel müdahale olmadan sürecinizi devam ettirebilirsiniz.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'Secure Controls Framework (SCF) Extra, Secure Controls Framework ile SimpleRisk arasında doğrudan bir entegrasyondur. SCF\'nin kontrol kataloğunu ve bu kontrollerin çok çeşitli uyumluluk ve siber güvenlik çerçeveleri genelindeki eşlemelerini SimpleRisk\'in Yönetişim işlevselliğine aktarır; böylece ihtiyaç duyduğunuz çerçeveleri benimseyebilir ve kontrollerini elle oluşturmadan yönetebilirsiniz.',

    // Configure Hub - tile descriptions (maintenance category)
