    'EncryptionRestoreBodyWhat'             => 'Yedekleme oluşturulduktan sonra veritabanına yazılan her satır kalıcı olarak kaybolacaktır — riskler, risk azaltma işlemleri, denetim günlüğü kayıtları ve etkinleştirmeden bu yana yapılan diğer tüm değişiklikler dahil. Şifreli Veritabanı Ekstrası, geri yükleme kapsamında devre dışı bırakılacaktır.',
