    // Queued email send-failure notifications
    'EmailSendFailedNotificationTitle' => 'E-posta Gönderimi Başarısız Oldu',
    'EmailSendFailedNotificationBody' => 'Kuyruktaki bir veya daha fazla e-posta teslim edilemedi. E-posta ayarlarınızı kontrol edin, ardından ayrıntılar için Kuyruk İzleyicisi\'ni ve sunucu günlüğünü görün.',
