    // controls", which read as a stutter once the label carried those words.
    'GetFrameworkFromScf' => 'Secure Controls Framework\'ten al',
    'GetFrameworkFromScfHint' => 'Yayımlanmış bir çerçeve seçin ve eşlenen kontrollerini tek adımda yükleyin.',
    'ImportFrameworkFromCatalog' => 'Birini içe aktar',
    'ImportFrameworkFromCatalogHint' => 'SimpleRisk içerik kataloğundan bir çerçeve ve kontrollerini yükleyin.',

    // The framework acquisition chooser's third route, which now offers the
