    'ImportFrameworkFromSpreadsheet' => 'Elektronik tablodan içe aktar',
    'ImportFrameworkFromSpreadsheetHint' => 'Çerçeveyi adlandıran bir kontrol elektronik tablosu yükleyin; ikisi de oluşturulur.',

    // The Define Control Frameworks rail's second synthetic scope: the controls
