    // Per-field help popovers on the CVSS holder's 14 metric selects
    // (buildCvssScoreItem(), risk-details-form.js) -- one per CVSS v2
    // metric, matching the standard CVSS v2 specification definitions.
    // Double-quoted (not single-quoted, this file's usual style) so the
    // \n line breaks are real escape sequences: each popover leads with one
    // overall sentence, then one bullet line per option, rendered via
    // white-space: pre-line on .sr-scoring-help-popover .popover-body
    // (scss/modules/_questionnaire.scss) -- plain text throughout, no HTML,
    // so the popover stays initialized without Bootstrap's `html: true`.
    "AttackVectorHelp" => 'Zafiyete nasıl erişilebileceği.
• Yerel: konsol veya kabuk gibi yerel erişim gerektirir.
• Bitişik Ağ: saldırganın aynı fiziksel veya mantıksal ağ segmentinde olması gerekir.
• Ağ: yerel veya bitişik erişim gerekmeden bir ağ üzerinden uzaktan istismar edilebilir.',
    "AttackComplexityHelp" => "Saldırgan hedefe erişim sağladıktan sonra saldırının ne kadar karmaşık olduğu.\n• Yüksek: Düzenlenmesi zor olan özel koşullar gerektirir.\n• Orta: Bazı koşulların karşılanması gerekir, ancak karşılandıktan sonra istismar zor değildir.\n• Düşük: Özel koşullara gerek yoktur.",
    "AuthenticationHelp" => "Saldırganın hedefi istismar etmek için kaç kez kimlik doğrulaması yapması gerektiği.\n• Çoklu: Aynı kimlik bilgileriyle bile olsa iki veya daha fazla kez kimlik doğrulaması gereklidir.\n• Tekli: Bir kez kimlik doğrulaması gereklidir.\n• Hiçbiri: Kimlik doğrulaması gerekmez.",
    "ConfidentialityImpactHelp" => 'İstismar edilmesi durumunda sistemin işlediği verilerin gizliliği üzerindeki etki.
• Yok: etki yok.
• Kısmi: bazı bilgiler ifşa olur, ancak saldırgan neyin ifşa olacağını kontrol edemez veya kayıp sınırlıdır.
• Tam: sistemdeki tüm bilgilerin tamamen ifşa olması.',
    "IntegrityImpactHelp" => 'İstismar edilmesi durumunda sistemin bütünlüğü üzerindeki etki.
• Yok: etki yok.
• Kısmi: bazı veriler değiştirilebilir, ancak saldırgan neyin değişeceğini kontrol edemez veya kapsam sınırlıdır.
• Tam: sistem bütünlüğünün tamamen ele geçirilmesi; saldırgan tüm dosyaları değiştirebilir.',
    "AvailabilityImpactHelp" => 'İstismar edilmesi durumunda sistemin erişilebilirliği üzerindeki etki.
• Yok: etki yok.
• Kısmi: performansta düşüş veya erişilebilirlikte kesintiler.
• Tam: etkilenen kaynağın tamamen kapanması.',
    "RemediationLevelHelp" => 'Zafiyet için mevcut düzeltme düzeyi.
• Resmi Düzeltme: satıcıdan tam bir çözüm mevcuttur.
• Geçici Düzeltme: resmi ancak geçici bir düzeltme mevcuttur.
• Geçici Çözüm: resmi olmayan, satıcı dışı bir geçici çözüm vardır.
• Mevcut Değil: hiçbir çözüm mevcut değildir veya uygulanamaz.',
    "ReportConfidenceHelp" => 'Zafiyetin varlığına ve teknik ayrıntılarının güvenilirliğine duyulan güven derecesi.
• Doğrulanmamış: tek ve doğrulanmamış bir kaynak raporu; altta yatan sorun varsayımsaldır.
• Teyit Edilmemiş: birden fazla bağımsız kaynak aynı davranışı bildiriyor, ancak kök neden doğrulanmamıştır.
• Doğrulanmış: satıcı sorunu kabul etmiştir veya kaynak kod ya da istismar analiziyle doğrulanmıştır.',
    "CollateralDamagePotentialHelp" => 'Zafiyet istismar edilirse can kaybı, fiziksel varlık kaybı veya mali kayıp potansiyeli.
• Yok: böyle bir kayıp olası değildir.
• Düşük ile Orta arası: orta düzeyde bir kayıp mümkündür.
• Yüksek: kuruluşun varlıkları, geliri veya güvenliği üzerinde yıkıcı bir etki.',
    "TargetDistributionHelp" => "Ortamınızdaki savunmasız sistemlerin oranı.\n• Yok: Hedef sistem yok.\n• Düşük: Sistemlerin %1-25'i savunmasız.\n• Orta: %26-75'i savunmasız.\n• Yüksek: %76-100'ü savunmasız.",
    "ConfidentialityRequirementHelp" => "Etkilenen varlığın gizliliğinin kuruluşunuz için ne kadar önemli olduğu.\n• Düşük: Gizlilik kaybının etkisi sınırlıdır.\n• Orta: Ciddi bir etkisi vardır.\n• Yüksek: Felaket niteliğinde bir etkisi vardır.",
    "IntegrityRequirementHelp" => "Etkilenen varlığın bütünlüğünün kuruluşunuz için ne kadar önemli olduğu.\n• Düşük: Bütünlük kaybının etkisi sınırlıdır.\n• Orta: Ciddi bir etkisi vardır.\n• Yüksek: Felaket niteliğinde bir etkisi vardır.",
    "AvailabilityRequirementHelp" => "Etkilenen varlığın kullanılabilirliğinin kuruluşunuz için ne kadar önemli olduğu.\n• Düşük: Kullanılabilirlik kaybının etkisi sınırlıdır.\n• Orta: Ciddi bir etkisi vardır.\n• Yüksek: Felaket niteliğinde bir etkisi vardır.",
    // Base Score Metrics' two sub-group intro sentences (metricsSubGroup()'s
    // `descKey`, risk-details-form.js) -- orient the user to what the GROUP
    // as a whole is asking, distinct from the per-field *Help popover keys
    // above which explain each metric's own options.
    'BaseScoreExploitabilityMetricsDescription' => 'Bir saldırganın bu güvenlik açığına nasıl ulaşıp onu tetikleyeceği: nerede olması gerektiği, saldırının ne kadar karmaşık olduğu ve önce kimlik doğrulaması yapması gerekip gerekmediği.',
    'BaseScoreImpactMetricsDescription' => 'Güvenlik açığının başarılı bir şekilde istismar edilmesi durumunda neler olur: etkilenen sistemin gizliliği, bütünlüğü ve kullanılabilirliği üzerindeki etkisi.',
    // Advanced Metrics' three optional sub-group intro sentences -- same
    // metricsSubGroup() `descKey` as the two Base Score groups above.
    'TemporalScoreMetricsDescription' => 'Bu güvenlik açığının gerçek dünyadaki tehdidinin zaman içinde nasıl değiştiği: istismar kodunun mevcut durumu, mevcut çözüm yolları ve varlığına dair raporların ne kadar güvenilir olduğu.',
    'EnvironmentalScoreMetricsDescription' => 'Bu güvenlik açığının riskinin ortamınıza nasıl bağlı olduğu: gerçek dünyada hasar verme potansiyeli ve sistemlerinizden kaçının gerçekten etkilendiği.',
    'ImpactSubscoreModifiersDescription' => 'Temel Puanın etkisini, gizlilik, bütünlük ve erişilebilirliğin bu belirli varlık için gerçekte ne kadar önemli olduğuna göre ağırlıklandırın.',
    // Phase 4d-iii: DREAD holder help popovers (view_dread_help()'s
    // existing English text, includes/display.php, extracted to real $lang
    // keys -- that function's own content was raw hardcoded HTML, never
    // localized, so it could not be reused verbatim).
    'DamagePotentialHelp' => 'Bir tehdit istismarı gerçekleşirse ne kadar hasar oluşur?
0 = Hiçbir şey
5 = Münferit kullanıcı verileri ele geçirilir veya etkilenir.
10 = Sistemin veya verilerin tamamen yok olması',
    'ReproducibilityHelp' => 'Bu tehdit saldırısının tekrarlanması ne kadar kolay?' . "\n" . '0 = Uygulama yöneticileri için bile çok zor veya imkansız.' . "\n" . '5 = Bir veya iki adım gereklidir, yetkili kullanıcı olmanız gerekebilir.' . "\n" . '10 = Kimlik doğrulaması olmadan, yalnızca bir web tarayıcısı ve adres çubuğu yeterlidir.',
    'ExploitabilityHelp' => 'Bu tehdidi istismar etmek için ne gerekir?
0 = Özel veya gelişmiş saldırı araçlarıyla birlikte ileri düzey programlama ve ağ bilgisi.
5 = İnternet\'te kötü amaçlı yazılım vardır veya mevcut saldırı araçlarıyla istismar kolayca gerçekleştirilir.
10 = Yalnızca bir web tarayıcısı',
    'AffectedUsersHelp' => 'Kaç kullanıcı etkilenecek?
0 = Hiçbiri
5 = Bazı kullanıcılar, ancak tamamı değil
10 = Tüm kullanıcılar',
    'DiscoverabilityHelp' => 'Bu tehdidi keşfetmek ne kadar kolaydır?
0 = Çok zordan imkânsıza kadar; kaynak kodu veya yönetici erişimi gerektirir.
5 = Tahmin yoluyla veya ağ izlerini izleyerek çözülebilir.
9 = Bu tür hataların ayrıntıları zaten kamuya açıktır ve bir arama motoru kullanılarak kolayca keşfedilebilir.
10 = Bilgi, web tarayıcısının adres çubuğunda veya bir formda görünür.',
    // The DREAD holder's summary card heading and "DREAD Metrics" card
