    'ReputationDamageHelp' => 'Bir güvenlik açığının kullanılması, işletmenin itibarını zedeleyerek zarar verebilir mi?' . "\n" . '1 = Minimum Hasar' . "\n" . '4 = Önemli Müşteri Kayıpları' . "\n" . '5 = İtibar Kaybı' . "\n" . '9 = Marka Hasarı',
